// Figma Components v2 > Icon (24px)에서 내보낸 경로를 그대로 옮겼다.
// 선 두께는 아이콘마다 다르므로(2 / 1.8) Figma 값을 유지한다.
function line(d: string, width: 1.8 | 2 = 2) {
  return (
    <path
      key={d}
      d={d}
      stroke="currentColor"
      strokeWidth={width}
      strokeLinecap="round"
      strokeLinejoin="round"
    />
  );
}

function solid(d: string) {
  return <path key={d} d={d} fill="currentColor" />;
}

